export default Controls;

import React, { useState } from 'react';
import { Employee, ShiftType, ShiftSymbol, SchedulingConfig, ThursdayScenario, Tool } from '../types';
import { CELL_STYLES, WEEKDAYS } from '../constants';
import { getDailyRequirements, getSpecialHolidayName } from '../services/scheduleGenerator';
import { ChevronDown, ChevronUp } from 'lucide-react';

interface RosterTableProps {
  year: number;
  month: number;
  employees: Employee[];
  baseTarget: number;
  onCellClick: (empIndex: number, day: number, shiftClicked?: ShiftType) => void;
  selectedSymbol: Tool;
  config: SchedulingConfig;
  activeScenario: ThursdayScenario;
  usedTuesdayReduction: boolean;
}

const ShiftBadge: React.FC<{ type: ShiftType }> = ({ type }) => {
  // If type is Xa, Xb, Xc, display 'X', otherwise display the type
  const label = type.startsWith('X') ? 'X' : type;

  return (
      <div className={`flex items-center justify-center w-full h-full text-sm font-bold print:text-base print:text-black ${CELL_STYLES[type] ? CELL_STYLES[type].replace('border border-gray-400', '') : 'text-gray-900'}`}>
          {label}
      </div>
  );
};

const SymbolBadge: React.FC<{ symbol: ShiftSymbol }> = ({ symbol }) => {
    return (
        <div className={`flex items-center justify-center w-full h-full text-xs font-bold print:text-xs ${CELL_STYLES[symbol] || ''}`}>
            {symbol}
        </div>
    );
};

const RosterTable: React.FC<RosterTableProps> = ({ 
    year, month, employees, baseTarget, onCellClick, selectedSymbol,
    config, activeScenario, usedTuesdayReduction
}) => {
  const [isStatsExpanded, setIsStatsExpanded] = useState(true);
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  const getDayInfo = (day: number) => {
    const date = new Date(year, month, day);
    const dow = date.getDay(); // 0=Sun
    const specialHoliday = getSpecialHolidayName(year, month, day);
    return {
      dow,
      label: WEEKDAYS[dow],
      isWeekend: dow === 0 || dow === 6,
      isSunday: dow === 0,
      isSaturday: dow === 6,
      specialHoliday
    };
  };

  const handleCellClick = (idx: number, day: number, shiftType?: ShiftType) => {
      const { isSunday } = getDayInfo(day);
      if (isSunday) return; // Prevent clicking on Sunday
      onCellClick(idx, day, shiftType);
  };

  return (
    <div className="flex-1 overflow-hidden flex flex-col relative bg-white shadow-sm border-t border-gray-200 print:shadow-none print:border-0 print:block print:overflow-visible print:h-auto">

      {/* Print Only Header */}
      <div className="hidden print:block mb-4 px-4 pt-4">
          <div className="flex justify-between items-end border-b-2 border-black pb-2">
              <div>
                  <h1 className="text-2xl font-bold text-black">{year}年 {month + 1}月 員工排班表</h1>
                  <p className="text-sm text-gray-600 mt-1">
                    目標節數: {baseTarget} / 週四模式: {activeScenario} {usedTuesdayReduction ? '+ 週二減員' : ''}
                  </p>
              </div>
              <div className="text-right text-xs text-gray-500">
                  列印日期: {new Date().toLocaleDateString()}
              </div>
          </div>
      </div>

      <div className="overflow-auto flex-1 pb-4 bg-white print:overflow-visible print:pb-0">
        <table className="min-w-max border-collapse text-xs w-full print:text-[10px] print:w-full">
          <thead className="bg-white sticky top-0 z-20 shadow-sm print:static print:shadow-none print:table-header-group">
            <tr>
              {/* Employee Name Header */}
              <th className="sticky left-0 z-30 bg-white border border-gray-300 p-1 min-w-[80px] w-[80px] text-center text-sm font-bold text-gray-700 print:border-black print:static print:bg-transparent print:w-auto print:min-w-0">
                員工
              </th>
              {/* Shift Label Header */}
              <th className="sticky left-[80px] z-30 bg-white border border-gray-300 p-0.5 min-w-[24px] w-[24px] text-center text-[10px] font-bold text-gray-700 print:border-black print:static print:bg-transparent print:w-auto print:min-w-0">
                班
              </th>

              {daysArray.map(day => {
                const { label, isSunday, isSaturday, specialHoliday } = getDayInfo(day);
                return (
                  <th key={day} className={`border border-gray-300 p-0 w-[32px] min-w-[32px] text-center h-10 align-middle print:border-black print:h-10 print:w-[32px] print:min-w-[32px] ${isSunday ? 'bg-red-50' : isSaturday ? 'bg-green-50' : 'bg-gray-50'}`}>
                    <div className="flex flex-col items-center justify-center h-full relative">
                      <span className="text-[10px] text-gray-500 leading-none mb-0.5 print:text-black print:text-xs">{day}</span>
                      <span className={`text-xs font-bold leading-none print:text-xs ${isSunday ? 'text-red-600' : isSaturday ? 'text-green-700' : 'text-gray-800'}`}>
                        {label}
                      </span>
                      {specialHoliday && (
                          <span className="text-[8px] text-purple-600 font-bold absolute bottom-0.5 scale-90 whitespace-nowrap print:text-[8px]">
                              {specialHoliday}
                          </span>
                      )}
                    </div>
                  </th>
                );
              })}
              {/* Reduced width for Stats column */}
              <th className="sticky right-0 z-30 bg-white border border-gray-300 p-1 w-[40px] min-w-[40px] text-center text-xs font-bold text-gray-700 print:border-black print:static print:bg-transparent print:min-w-[40px]">
                統計
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {employees.map((emp, idx) => {
               const effectiveTarget = (emp.customTarget ?? baseTarget) - emp.targetDeduction;
               const diff = emp.generatedShiftCount - effectiveTarget;

               // We render 3 rows per employee
               return (
                <React.Fragment key={emp.id}>
                    {/* Row 1: Morning (A) */}
                    <tr className="hover:bg-gray-50 transition-colors h-8 print:h-6 print:break-inside-avoid border-t-2 border-gray-300 print:border-black">
                        {/* Employee Name - RowSpan 3 */}
                        <td rowSpan={3} className="sticky left-0 z-10 bg-white border-r border-b border-gray-300 px-1 py-0 font-bold text-gray-800 text-center text-base shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] print:shadow-none print:border-black print:static print:text-xs align-middle">
                            {emp.name}
                        </td>

                        {/* Shift Label: A */}
                        <td className="sticky left-[80px] z-10 bg-gray-50/50 border-r border-b border-gray-300 text-center text-[10px] text-gray-500 font-medium align-middle print:border-black print:static print:text-xs">
                            早
                        </td>

                        {daysArray.map(day => {
                            const dateKey = `${year}-${month}-${day}`;
                            const cellData = emp.shifts[dateKey];
                            const { isSunday } = getDayInfo(day);
                            const isSymbol = !Array.isArray(cellData) && cellData;
                            const shifts = Array.isArray(cellData) ? cellData : [];

                            // If it's a symbol, we span 3 rows to show it clearly
                            if (isSymbol) {
                                return (
                                    <td 
                                        key={day} 
                                        rowSpan={3}
                                        onClick={() => handleCellClick(idx, day)}
                                        className={`border border-b border-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                            ${selectedSymbol ? 'cursor-cell' : ''}
                                            ${isSunday ? 'cursor-not-allowed opacity-50' : ''}
                                        `}
                                    >
                                        <SymbolBadge symbol={cellData as ShiftSymbol} />
                                    </td>
                                );
                            }

                            return (
                                <td 
                                    key={day} 
                                    onClick={() => handleCellClick(idx, day, 'A')}
                                    className={`border border-gray-200 border-r-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                        ${isSunday ? 'bg-red-50/30 cursor-not-allowed' : ''}
                                        ${selectedSymbol && !isSunday ? 'cursor-cell' : ''}
                                    `}
                                >
                                    <div className="flex items-center justify-center h-full w-full">
                                        {shifts.includes('A') && <ShiftBadge type="A" />}
                                        {shifts.includes('Xa') && <ShiftBadge type="Xa" />}
                                    </div>
                                </td>
                            );
                        })}

                        {/* Stats - RowSpan 3 */}
                        <td rowSpan={3} className="sticky right-0 z-10 bg-white border-l border-b border-gray-300 px-0.5 text-center shadow-[-2px_0_5px_-2px_rgba(0,0,0,0.1)] print:shadow-none print:border-black print:static align-middle">
                            <div className="flex flex-col items-center justify-center text-xs leading-tight print:text-xs">
                                <span className="font-bold text-indigo-600 text-sm print:text-black print:text-sm">{emp.generatedShiftCount}</span>
                                <span className="text-gray-400 text-[10px] print:text-gray-600">/ {effectiveTarget}</span>
                                {Math.abs(diff) > 2 && (
                                    <span className={`font-bold text-[10px] ${diff > 0 ? 'text-green-500' : 'text-red-500'} print:hidden`}>
                                        {diff > 0 ? `+${diff}` : diff}
                                    </span>
                                )}
                            </div>
                        </td>
                    </tr>

                    {/* Row 2: Afternoon (B) */}
                    <tr className="hover:bg-gray-50 transition-colors h-8 print:h-6 print:break-inside-avoid">
                        <td className="sticky left-[80px] z-10 bg-gray-50/50 border-r border-b border-gray-300 text-center text-[10px] text-gray-500 font-medium align-middle print:border-black print:static print:text-xs">
                            中
                        </td>
                         {daysArray.map(day => {
                            const dateKey = `${year}-${month}-${day}`;
                            const cellData = emp.shifts[dateKey];
                            const { isSunday } = getDayInfo(day);
                            const isSymbol = !Array.isArray(cellData) && cellData;
                            const shifts = Array.isArray(cellData) ? cellData : [];

                            if (isSymbol) return null; // Handled in Row 1

                            return (
                                <td 
                                    key={day} 
                                    onClick={() => handleCellClick(idx, day, 'B')}
                                    className={`border border-gray-200 border-r-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                        ${isSunday ? 'bg-red-50/30 cursor-not-allowed' : ''}
                                        ${selectedSymbol && !isSunday ? 'cursor-cell' : ''}
                                    `}
                                >
                                    <div className="flex items-center justify-center h-full w-full">
                                        {shifts.includes('B') && <ShiftBadge type="B" />}
                                        {shifts.includes('Xb') && <ShiftBadge type="Xb" />}
                                    </div>
                                </td>
                            );
                        })}
                    </tr>

                    {/* Row 3: Evening (C) */}
                    <tr className="hover:bg-gray-50 transition-colors h-8 print:h-6 print:break-inside-avoid">
                        <td className="sticky left-[80px] z-10 bg-gray-50/50 border-r border-b border-gray-300 text-center text-[10px] text-gray-500 font-medium align-middle print:border-black print:static print:text-xs">
                            晚
                        </td>
                        {daysArray.map(day => {
                            const dateKey = `${year}-${month}-${day}`;
                            const cellData = emp.shifts[dateKey];
                            const { isSunday } = getDayInfo(day);
                            const isSymbol = !Array.isArray(cellData) && cellData;
                            const shifts = Array.isArray(cellData) ? cellData : [];

                            if (isSymbol) return null; // Handled in Row 1

                            return (
                                <td 
                                    key={day} 
                                    onClick={() => handleCellClick(idx, day, 'C')}
                                    className={`border border-b border-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                        ${isSunday ? 'bg-red-50/30 cursor-not-allowed' : ''}
                                        ${selectedSymbol && !isSunday ? 'cursor-cell' : ''}
                                    `}
                                >
                                    <div className="flex items-center justify-center h-full w-full">
                                        {shifts.includes('C') && <ShiftBadge type="C" />}
                                        {shifts.includes('Xc') && <ShiftBadge type="Xc" />}
                                    </div>
                                </td>
                            );
                        })}
                    </tr>
                </React.Fragment>
               );
            })}
          </tbody>

          <tfoot className="bg-gray-50 sticky bottom-0 z-20 shadow-[0_-2px_4px_rgba(0,0,0,0.1)] print:table-footer-group print:shadow-none print:static transition-all duration-300">
            <tr>
              {/* Footer needs to span 2 cols (Employee + Shift Label) */}
              <td colSpan={2} className="sticky left-0 z-30 bg-gray-100 border border-gray-300 p-0 font-bold text-gray-600 text-center text-xs print:border-black print:static print:bg-transparent">
                <button 
                  onClick={() => setIsStatsExpanded(!isStatsExpanded)}
                  className="w-full h-full flex items-center justify-center gap-1 py-2 hover:bg-gray-200 transition-colors focus:outline-none"
                  title={isStatsExpanded ? "摺疊統計" : "展開統計"}
                >
                  統計
                  {isStatsExpanded ? <ChevronDown className="w-3 h-3" /> : <ChevronUp className="w-3 h-3" />}
                </button>
              </td>
              {daysArray.map(day => {
                  const date = new Date(year, month, day);
                  const dateKey = `${year}-${month}-${day}`;
                  const { isSunday } = getDayInfo(day);
                  const req = getDailyRequirements(date, config, activeScenario, usedTuesdayReduction);

                  // Calculate actual counts
                  let countA = 0, countB = 0, countC = 0;
                  employees.forEach(e => {
                      const cell = e.shifts[dateKey];
                      if (Array.isArray(cell)) {
                          if (cell.includes('A')) countA++;
                          if (cell.includes('B')) countB++;
                          if (cell.includes('C')) countC++;
                      }
                  });

                  if (isSunday) return <td key={day} className="border border-gray-300 bg-red-50/50 print:border-black"></td>;

                  const badA = countA !== req.A;
                  const badB = countB !== req.B;
                  const badC = countC !== req.C;

                  // Use Green text for reduced days (e.g. Tue B=4) to show it's valid
                  const isReduced = usedTuesdayReduction && date.getDay() === 2;

                  if (!isStatsExpanded) {
                      const hasError = badA || badB || badC;
                      return (
                          <td key={day} className={`border border-gray-300 p-0.5 h-6 print:border-black ${hasError ? 'bg-red-50' : ''}`}>
                              {hasError && <div className="w-2 h-2 rounded-full bg-red-500 mx-auto"></div>}
                          </td>
                      );
                  }

                  return (
                      <td key={day} className="border border-gray-300 p-0.5 align-top print:border-black">
                          <div className="flex flex-col items-center text-[10px] leading-tight py-1 print:text-[8px]">
                              {req.A > 0 && (
                                  <div className={badA ? 'text-red-600 font-bold' : 'text-gray-500 print:text-black'}>
                                      A:{countA}
                                  </div>
                              )}
                              {req.B > 0 && (
                                  <div className={badB ? 'text-red-600 font-bold' : isReduced ? 'text-green-600 font-bold' : 'text-gray-500 print:text-black'}>
                                      B:{countB}
                                  </div>
                              )}
                              {req.C > 0 && (
                                  <div className={badC ? 'text-red-600 font-bold' : isReduced ? 'text-green-600 font-bold' : 'text-gray-500 print:text-black'}>
                                      C:{countC}
                                  </div>
                              )}
                          </div>
                      </td>
                  );
              })}
              <td className="sticky right-0 z-30 bg-gray-100 border border-gray-300 print:border-black print:static"></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

export default RosterTable;

import React, { useState, useEffect } from 'react';
import Controls from './components/Controls';
import RosterTable from './components/RosterTable';
import ClearModal from './components/ClearModal';
import { SchedulingConfig, Employee, ThursdayScenario, Tool, ShiftType } from './types';
import { DEFAULT_STAFF_NAMES } from './constants';
import { generateSchedule, calculateBaseTarget, validateSchedule, recalculateEmployeeStats, calculateOverviewStats } from './services/scheduleGenerator';
import { AlertCircle } from 'lucide-react';

const STORAGE_KEY = 'shiftflow_data_v1';

const App: React.FC = () => {
  const today = new Date();

  // -- State --
  const [employees, setEmployees] = useState<Employee[]>(
    DEFAULT_STAFF_NAMES.map((name, idx) => ({
      id: (idx + 1).toString(),
      name,
      shifts: {},
      manualEntries: {},
      generatedShiftCount: 0,
      targetDeduction: 0
    }))
  );

  const [config, setConfig] = useState<SchedulingConfig>({
    year: today.getFullYear(),
    month: today.getMonth(),
    staffIds: DEFAULT_STAFF_NAMES.map((_, idx) => (idx + 1).toString()),

    reqStandardA: 5,
    reqStandardB: 5,
    reqStandardC: 5,
    reqSaturdayA: 5,
    thursdayMode: 'Auto',
    yearHolidayStart: '', // Initialize empty string for dates
    yearHolidayEnd: '',
    jan1WorkDay: false
  });

  const [warnings, setWarnings] = useState<string[]>([]);
  const [baseTarget, setBaseTarget] = useState(0);
  const [stats, setStats] = useState<{totalDemand: number, totalCapacity: number, suggestedSpecialLeaves: number} | undefined>(undefined);
  const [activeThursdayScenario, setActiveThursdayScenario] = useState<ThursdayScenario>(ThursdayScenario.A);
  const [usedTuesdayReduction, setUsedTuesdayReduction] = useState(false);

  const [selectedSymbol, setSelectedSymbol] = useState<Tool>(null);

  // New state for modal and redraw
  const [isClearModalOpen, setIsClearModalOpen] = useState(false);
  const [gridKey, setGridKey] = useState(0);

  // -- Persistence --
  useEffect(() => {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
          try {
              const parsed = JSON.parse(saved);
              if (parsed.config) {
                 // Backward compatibility migration for yearHolidayCount
                 const loadedConfig = parsed.config;
                 if (loadedConfig.yearHolidayCount !== undefined) {
                     delete loadedConfig.yearHolidayCount;
                     loadedConfig.yearHolidayStart = '';
                     loadedConfig.yearHolidayEnd = '';
                 }
                 if (loadedConfig.jan1WorkDay === undefined) {
                     loadedConfig.jan1WorkDay = false;
                 }
                 setConfig(loadedConfig);
              }
              if (parsed.employees) {
                  // Ensure manualEntries exists on loaded data
                  const loadedEmployees = parsed.employees.map((e: any) => ({
                      ...e,
                      manualEntries: e.manualEntries || {}
                  }));
                  setEmployees(loadedEmployees);
              }
              if (parsed.stats) setStats(parsed.stats);
              if (parsed.activeThursdayScenario) setActiveThursdayScenario(parsed.activeThursdayScenario);
              if (parsed.usedTuesdayReduction) setUsedTuesdayReduction(parsed.usedTuesdayReduction);
          } catch (e) {
              console.error("Failed to load saved data", e);
          }
      }
  }, []);

  useEffect(() => {
      const data = { config, employees, stats, activeThursdayScenario, usedTuesdayReduction };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [config, employees, stats, activeThursdayScenario, usedTuesdayReduction]);


  // -- Effects --
  useEffect(() => {
     // 1. Update Base Target calculation
     setBaseTarget(calculateBaseTarget(config.year, config.month, config.yearHolidayStart, config.yearHolidayEnd, config.jan1WorkDay));

     // 2. Recalculate employee stats for the new month view
     // This ensures that targetDeduction (from special leaves) and shift counts 
     // reflect ONLY the current viewed month.
     const updatedEmployees = employees.map(emp => recalculateEmployeeStats(emp, config.year, config.month));
     setEmployees(updatedEmployees);

     // 3. Immediately Calculate Overview Stats based on current config & employees
     const newStats = calculateOverviewStats(config, updatedEmployees, activeThursdayScenario, usedTuesdayReduction);
     setStats(newStats);

  }, [config.year, config.month, config.yearHolidayStart, config.yearHolidayEnd, config.jan1WorkDay, config.reqStandardA, config.reqStandardB, config.reqStandardC, config.reqSaturdayA]);

  // Real-time validation
  useEffect(() => {
    // Whenever employees or config changes, re-run validation
    const newWarnings = validateSchedule(employees, config, activeThursdayScenario, usedTuesdayReduction);
    setWarnings(newWarnings);
  }, [employees, config, activeThursdayScenario, usedTuesdayReduction]);

  // -- Handlers --

  const handleGenerate = () => {
    // When generating, we pass the current state. 
    const result = generateSchedule(config, employees);

    setEmployees(result.employees);
    setWarnings(result.warnings);
    setStats(result.stats);
    setActiveThursdayScenario(result.usedThursdayScenario);
    setUsedTuesdayReduction(result.usedTuesdayReduction);
    setGridKey(prev => prev + 1); // Force redraw on generation too
  };

  const handleClear = (mode: 'generated' | 'all') => {
      const prefix = `${config.year}-${config.month}-`;

      const newEmployees = employees.map(emp => {
          // Strict iteration over employee data
          const newShifts = { ...emp.shifts };
          const newManualEntries = { ...(emp.manualEntries || {}) };

          Object.keys(newShifts).forEach(key => {
              // Ensure we are only touching the current month
              if (!key.startsWith(prefix)) return;

              const cellValue = newShifts[key];
              const isManual = newManualEntries[key];

              if (mode === 'all') {
                  // Hard reset: delete everything
                  delete newShifts[key];
                  delete newManualEntries[key];
              } else if (mode === 'generated') {
                  // Soft reset: only delete if it's an array (generated shifts) AND NOT MANUAL
                  // Keep if it's a string (Symbol) OR if it was manually entered
                  if (Array.isArray(cellValue) && !isManual) {
                      delete newShifts[key];
                  }
              }
          });

          return recalculateEmployeeStats({
              ...emp,
              shifts: newShifts,
              manualEntries: newManualEntries
          }, config.year, config.month);
      });

      setEmployees(newEmployees);
      setIsClearModalOpen(false);
      setGridKey(prev => prev + 1); // FORCE REACT TO RE-RENDER THE TABLE

      if (mode === 'all') {
          // Recalculate empty stats
          const emptyStats = calculateOverviewStats(config, newEmployees, ThursdayScenario.A, false);
          setStats(emptyStats);
          setActiveThursdayScenario(ThursdayScenario.A);
          setUsedTuesdayReduction(false);
      }
  };

  const handleCellClick = (empIndex: number, day: number, shiftClicked?: ShiftType) => {
      const dateKey = `${config.year}-${config.month}-${day}`;
      const newEmployees = [...employees];
      const emp = newEmployees[empIndex];
      const newShifts = { ...emp.shifts };
      const newManualEntries = { ...(emp.manualEntries || {}) }; // Clone manual entries

      const currentVal = newShifts[dateKey];

      // 1. ERASER MODE
      if (selectedSymbol === 'eraser') {
          if (Array.isArray(currentVal) && shiftClicked) {
              // Remove specific shift (e.g. remove B from [A, B])
              const newVal = currentVal.filter(s => {
                  // If we click B, remove B. If we click B but it has Xb, remove Xb.
                  if (shiftClicked === 'A') return s !== 'A' && s !== 'Xa';
                  if (shiftClicked === 'B') return s !== 'B' && s !== 'Xb';
                  if (shiftClicked === 'C') return s !== 'C' && s !== 'Xc';
                  return s !== shiftClicked;
              });

              if (newVal.length === 0) {
                  delete newShifts[dateKey];
                  delete newManualEntries[dateKey]; // Clear manual flag if empty
              } else {
                  newShifts[dateKey] = newVal;
                  newManualEntries[dateKey] = true; // Partial edit is still manual
              }
          } else {
              // Remove everything (Symbol or click on whole cell)
              delete newShifts[dateKey];
              delete newManualEntries[dateKey];
          }
      } 
      // 2. FULL SYMBOL MODE (O, 特... excluding positional X)
      else if (selectedSymbol && !['A', 'B', 'C', 'X'].includes(selectedSymbol)) {
          newShifts[dateKey] = selectedSymbol as string;
          newManualEntries[dateKey] = true; // Mark as manual
      }
      // 3. POINTER / TOGGLE MODE (A, B, C, X)
      else {
          // Determine which shift we are interacting with
          let targetShift = selectedSymbol ? (selectedSymbol as ShiftType) : shiftClicked;

          // Special handling for 'X' tool to map to positional Xa, Xb, Xc
          if (targetShift === 'X') {
              if (shiftClicked === 'A') targetShift = 'Xa';
              else if (shiftClicked === 'B') targetShift = 'Xb';
              else if (shiftClicked === 'C') targetShift = 'Xc';
          }

          if (targetShift) {
              // Start with empty array if current is symbol or undefined
              let currentArr: ShiftType[] = [];
              if (Array.isArray(currentVal)) {
                  currentArr = [...currentVal];
              }

              // Toggle Logic
              if (currentArr.includes(targetShift)) {
                  // If tool matches existing, remove it (Toggle Off)
                  currentArr = currentArr.filter(s => s !== targetShift);
              } else {
                  // Add it (Toggle On)
                  currentArr.push(targetShift);

                  // Special logic: If adding 'Xa', remove 'A'. If adding 'A', remove 'Xa'. Mutually exclusive in one slot.
                  if (targetShift === 'Xa') currentArr = currentArr.filter(s => s !== 'A');
                  if (targetShift === 'A') currentArr = currentArr.filter(s => s !== 'Xa');

                  if (targetShift === 'Xb') currentArr = currentArr.filter(s => s !== 'B');
                  if (targetShift === 'B') currentArr = currentArr.filter(s => s !== 'Xb');

                  if (targetShift === 'Xc') currentArr = currentArr.filter(s => s !== 'C');
                  if (targetShift === 'C') currentArr = currentArr.filter(s => s !== 'Xc');

                  // Sort order (A/Xa -> B/Xb -> C/Xc)
                  const sortOrder: Record<string, number> = { 'A':1, 'Xa':1, 'B':2, 'Xb':2, 'C':3, 'Xc':3 };
                  currentArr.sort((a, b) => (sortOrder[a] || 99) - (sortOrder[b] || 99));
              }

              if (currentArr.length === 0) {
                  delete newShifts[dateKey];
                  delete newManualEntries[dateKey];
              } else {
                  newShifts[dateKey] = currentArr;
                  newManualEntries[dateKey] = true; // Mark as manual
              }
          }
      }

      emp.shifts = newShifts;
      emp.manualEntries = newManualEntries; // Save back

      // Recalculate stats immediately
      newEmployees[empIndex] = recalculateEmployeeStats(emp, config.year, config.month);
      setEmployees(newEmployees);

      // Re-update total stats
      const newStats = calculateOverviewStats(config, newEmployees, activeThursdayScenario, usedTuesdayReduction);
      setStats(newStats);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-100 font-sans print:bg-white print:h-auto print:block print:overflow-visible">
      <Controls 
        config={config} 
        setConfig={setConfig} 
        employees={employees}
        setEmployees={setEmployees}
        onGenerate={handleGenerate}
        baseTarget={baseTarget}
        stats={stats}
        selectedSymbol={selectedSymbol}
        setSelectedSymbol={setSelectedSymbol}
        onOpenClearModal={() => setIsClearModalOpen(true)}
        activeScenario={activeThursdayScenario}
        usedTuesdayReduction={usedTuesdayReduction}
      />

      <ClearModal 
        isOpen={isClearModalOpen}
        onClose={() => setIsClearModalOpen(false)}
        onConfirm={handleClear}
        monthLabel={`${config.year}年${config.month + 1}月`}
      />

      {warnings.length > 0 && (
          <div className="bg-yellow-50 border-b border-yellow-200 px-6 py-2 flex-shrink-0 print:hidden">
            <div className="flex items-start gap-2 max-w-7xl mx-auto">
                <AlertCircle className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" />
                <div className="text-sm text-yellow-700 max-h-20 overflow-y-auto w-full">
                    <p className="font-semibold">排班警告 ({warnings.length})：</p>
                    <ul className="list-disc pl-4 space-y-1">
                        {warnings.slice(0, 3).map((w, i) => <li key={i}>{w}</li>)}
                        {warnings.length > 3 && <li>...以及其他 {warnings.length - 3} 個問題。</li>}
                    </ul>
                </div>
            </div>
          </div>
      )}

      <RosterTable 
        key={gridKey}
        year={config.year}
        month={config.month}
        employees={employees}
        baseTarget={baseTarget}
        onCellClick={handleCellClick}
        selectedSymbol={selectedSymbol}
        config={config}
        activeScenario={activeThursdayScenario}
        usedTuesdayReduction={usedTuesdayReduction}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Controls from './components/Controls';
import RosterTable from './components/RosterTable';
import ClearModal from './components/ClearModal';
import { SchedulingConfig, Employee, ThursdayScenario, Tool, ShiftType } from './types';
import { DEFAULT_STAFF_NAMES } from './constants';
import { generateSchedule, calculateBaseTarget, validateSchedule, recalculateEmployeeStats, calculateOverviewStats } from './services/scheduleGenerator';
import { AlertCircle } from 'lucide-react';

const STORAGE_KEY = 'shiftflow_data_v1';

const App: React.FC = () => {
  const today = new Date();

  // -- State --
  const [employees, setEmployees] = useState<Employee[]>(
    DEFAULT_STAFF_NAMES.map((name, idx) => ({
      id: (idx + 1).toString(),
      name,
      shifts: {},
      manualEntries: {},
      generatedShiftCount: 0,
      targetDeduction: 0
    }))
  );

  const [config, setConfig] = useState<SchedulingConfig>({
    year: today.getFullYear(),
    month: today.getMonth(),
    staffIds: DEFAULT_STAFF_NAMES.map((_, idx) => (idx + 1).toString()),

    reqStandardA: 5,
    reqStandardB: 5,
    reqStandardC: 5,
    reqSaturdayA: 5,
    thursdayMode: 'Auto',
    yearHolidayStart: '', // Initialize empty string for dates
    yearHolidayEnd: '',
    jan1WorkDay: false
  });

  const [warnings, setWarnings] = useState<string[]>([]);
  const [baseTarget, setBaseTarget] = useState(0);
  const [stats, setStats] = useState<{totalDemand: number, totalCapacity: number, suggestedSpecialLeaves: number} | undefined>(undefined);
  const [activeThursdayScenario, setActiveThursdayScenario] = useState<ThursdayScenario>(ThursdayScenario.A);
  const [usedTuesdayReduction, setUsedTuesdayReduction] = useState(false);

  const [selectedSymbol, setSelectedSymbol] = useState<Tool>(null);

  // New state for modal and redraw
  const [isClearModalOpen, setIsClearModalOpen] = useState(false);
  const [gridKey, setGridKey] = useState(0);

  // -- Persistence --
  useEffect(() => {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
          try {
              const parsed = JSON.parse(saved);
              if (parsed.config) {
                 // Backward compatibility migration for yearHolidayCount
                 const loadedConfig = parsed.config;
                 if (loadedConfig.yearHolidayCount !== undefined) {
                     delete loadedConfig.yearHolidayCount;
                     loadedConfig.yearHolidayStart = '';
                     loadedConfig.yearHolidayEnd = '';
                 }
                 if (loadedConfig.jan1WorkDay === undefined) {
                     loadedConfig.jan1WorkDay = false;
                 }
                 setConfig(loadedConfig);
              }
              if (parsed.employees) {
                  // Ensure manualEntries exists on loaded data
                  const loadedEmployees = parsed.employees.map((e: any) => ({
                      ...e,
                      manualEntries: e.manualEntries || {}
                  }));
                  setEmployees(loadedEmployees);
              }
              if (parsed.stats) setStats(parsed.stats);
              if (parsed.activeThursdayScenario) setActiveThursdayScenario(parsed.activeThursdayScenario);
              if (parsed.usedTuesdayReduction) setUsedTuesdayReduction(parsed.usedTuesdayReduction);
          } catch (e) {
              console.error("Failed to load saved data", e);
          }
      }
  }, []);

  useEffect(() => {
      const data = { config, employees, stats, activeThursdayScenario, usedTuesdayReduction };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [config, employees, stats, activeThursdayScenario, usedTuesdayReduction]);


  // -- Effects --
  useEffect(() => {
     // 1. Update Base Target calculation
     setBaseTarget(calculateBaseTarget(config.year, config.month, config.yearHolidayStart, config.yearHolidayEnd, config.jan1WorkDay));

     // 2. Recalculate employee stats for the new month view
     // This ensures that targetDeduction (from special leaves) and shift counts 
     // reflect ONLY the current viewed month.
     const updatedEmployees = employees.map(emp => recalculateEmployeeStats(emp, config.year, config.month));
     setEmployees(updatedEmployees);

     // 3. Immediately Calculate Overview Stats based on current config & employees
     const newStats = calculateOverviewStats(config, updatedEmployees, activeThursdayScenario, usedTuesdayReduction);
     setStats(newStats);

  }, [config.year, config.month, config.yearHolidayStart, config.yearHolidayEnd, config.jan1WorkDay, config.reqStandardA, config.reqStandardB, config.reqStandardC, config.reqSaturdayA]);

  // Real-time validation
  useEffect(() => {
    // Whenever employees or config changes, re-run validation
    const newWarnings = validateSchedule(employees, config, activeThursdayScenario, usedTuesdayReduction);
    setWarnings(newWarnings);
  }, [employees, config, activeThursdayScenario, usedTuesdayReduction]);

  // -- Handlers --

  const handleGenerate = () => {
    // When generating, we pass the current state. 
    const result = generateSchedule(config, employees);

    setEmployees(result.employees);
    setWarnings(result.warnings);
    setStats(result.stats);
    setActiveThursdayScenario(result.usedThursdayScenario);
    setUsedTuesdayReduction(result.usedTuesdayReduction);
    setGridKey(prev => prev + 1); // Force redraw on generation too
  };

  const handleClear = (mode: 'generated' | 'all') => {
      const prefix = `${config.year}-${config.month}-`;

      const newEmployees = employees.map(emp => {
          // Strict iteration over employee data
          const newShifts = { ...emp.shifts };
          const newManualEntries = { ...(emp.manualEntries || {}) };

          Object.keys(newShifts).forEach(key => {
              // Ensure we are only touching the current month
              if (!key.startsWith(prefix)) return;

              const cellValue = newShifts[key];
              const isManual = newManualEntries[key];

              if (mode === 'all') {
                  // Hard reset: delete everything
                  delete newShifts[key];
                  delete newManualEntries[key];
              } else if (mode === 'generated') {
                  // Soft reset: only delete if it's an array (generated shifts) AND NOT MANUAL
                  // Keep if it's a string (Symbol) OR if it was manually entered
                  if (Array.isArray(cellValue) && !isManual) {
                      delete newShifts[key];
                  }
              }
          });

          return recalculateEmployeeStats({
              ...emp,
              shifts: newShifts,
              manualEntries: newManualEntries
          }, config.year, config.month);
      });

      setEmployees(newEmployees);
      setIsClearModalOpen(false);
      setGridKey(prev => prev + 1); // FORCE REACT TO RE-RENDER THE TABLE

      if (mode === 'all') {
          // Recalculate empty stats
          const emptyStats = calculateOverviewStats(config, newEmployees, ThursdayScenario.A, false);
          setStats(emptyStats);
          setActiveThursdayScenario(ThursdayScenario.A);
          setUsedTuesdayReduction(false);
      }
  };

  const handleCellClick = (empIndex: number, day: number, shiftClicked?: ShiftType) => {
      const dateKey = `${config.year}-${config.month}-${day}`;
      const newEmployees = [...employees];
      const emp = newEmployees[empIndex];
      const newShifts = { ...emp.shifts };
      const newManualEntries = { ...(emp.manualEntries || {}) }; // Clone manual entries

      const currentVal = newShifts[dateKey];

      // 1. ERASER MODE
      if (selectedSymbol === 'eraser') {
          if (Array.isArray(currentVal) && shiftClicked) {
              // Remove specific shift (e.g. remove B from [A, B])
              const newVal = currentVal.filter(s => {
                  // If we click B, remove B. If we click B but it has Xb, remove Xb.
                  if (shiftClicked === 'A') return s !== 'A' && s !== 'Xa';
                  if (shiftClicked === 'B') return s !== 'B' && s !== 'Xb';
                  if (shiftClicked === 'C') return s !== 'C' && s !== 'Xc';
                  return s !== shiftClicked;
              });

              if (newVal.length === 0) {
                  delete newShifts[dateKey];
                  delete newManualEntries[dateKey]; // Clear manual flag if empty
              } else {
                  newShifts[dateKey] = newVal;
                  newManualEntries[dateKey] = true; // Partial edit is still manual
              }
          } else {
              // Remove everything (Symbol or click on whole cell)
              delete newShifts[dateKey];
              delete newManualEntries[dateKey];
          }
      } 
      // 2. FULL SYMBOL MODE (O, 特... excluding positional X)
      else if (selectedSymbol && !['A', 'B', 'C', 'X'].includes(selectedSymbol)) {
          newShifts[dateKey] = selectedSymbol as string;
          newManualEntries[dateKey] = true; // Mark as manual
      }
      // 3. POINTER / TOGGLE MODE (A, B, C, X)
      else {
          // Determine which shift we are interacting with
          let targetShift: string | undefined = selectedSymbol ? selectedSymbol : shiftClicked;

          // Special handling for 'X' tool to map to positional Xa, Xb, Xc
          if (targetShift === 'X') {
              if (shiftClicked === 'A') targetShift = 'Xa';
              else if (shiftClicked === 'B') targetShift = 'Xb';
              else if (shiftClicked === 'C') targetShift = 'Xc';
          }

          const validShifts: string[] = ['A', 'B', 'C', 'Xa', 'Xb', 'Xc'];

          if (targetShift && validShifts.includes(targetShift)) {
              const finalShift = targetShift as ShiftType;

              // Start with empty array if current is symbol or undefined
              let currentArr: ShiftType[] = [];
              if (Array.isArray(currentVal)) {
                  currentArr = [...currentVal];
              }

              // Toggle Logic
              if (currentArr.includes(finalShift)) {
                  // If tool matches existing, remove it (Toggle Off)
                  currentArr = currentArr.filter(s => s !== finalShift);
              } else {
                  // Add it (Toggle On)
                  currentArr.push(finalShift);

                  // Special logic: If adding 'Xa', remove 'A'. If adding 'A', remove 'Xa'. Mutually exclusive in one slot.
                  if (finalShift === 'Xa') currentArr = currentArr.filter(s => s !== 'A');
                  if (finalShift === 'A') currentArr = currentArr.filter(s => s !== 'Xa');

                  if (finalShift === 'Xb') currentArr = currentArr.filter(s => s !== 'B');
                  if (finalShift === 'B') currentArr = currentArr.filter(s => s !== 'Xb');

                  if (finalShift === 'Xc') currentArr = currentArr.filter(s => s !== 'C');
                  if (finalShift === 'C') currentArr = currentArr.filter(s => s !== 'Xc');

                  // Sort order (A/Xa -> B/Xb -> C/Xc)
                  const sortOrder: Record<string, number> = { 'A':1, 'Xa':1, 'B':2, 'Xb':2, 'C':3, 'Xc':3 };
                  currentArr.sort((a, b) => (sortOrder[a] || 99) - (sortOrder[b] || 99));
              }

              if (currentArr.length === 0) {
                  delete newShifts[dateKey];
                  delete newManualEntries[dateKey];
              } else {
                  newShifts[dateKey] = currentArr;
                  newManualEntries[dateKey] = true; // Mark as manual
              }
          }
      }

      emp.shifts = newShifts;
      emp.manualEntries = newManualEntries; // Save back

      // Recalculate stats immediately
      newEmployees[empIndex] = recalculateEmployeeStats(emp, config.year, config.month);
      setEmployees(newEmployees);

      // Re-update total stats
      const newStats = calculateOverviewStats(config, newEmployees, activeThursdayScenario, usedTuesdayReduction);
      setStats(newStats);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-100 font-sans print:bg-white print:h-auto print:block print:overflow-visible">
      <Controls 
        config={config} 
        setConfig={setConfig} 
        employees={employees}
        setEmployees={setEmployees}
        onGenerate={handleGenerate}
        baseTarget={baseTarget}
        stats={stats}
        selectedSymbol={selectedSymbol}
        setSelectedSymbol={setSelectedSymbol}
        onOpenClearModal={() => setIsClearModalOpen(true)}
        activeScenario={activeThursdayScenario}
        usedTuesdayReduction={usedTuesdayReduction}
      />

      <ClearModal 
        isOpen={isClearModalOpen}
        onClose={() => setIsClearModalOpen(false)}
        onConfirm={handleClear}
        monthLabel={`${config.year}年${config.month + 1}月`}
      />

      {warnings.length > 0 && (
          <div className="bg-yellow-50 border-b border-yellow-200 px-6 py-2 flex-shrink-0 print:hidden">
            <div className="flex items-start gap-2 max-w-7xl mx-auto">
                <AlertCircle className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" />
                <div className="text-sm text-yellow-700 max-h-20 overflow-y-auto w-full">
                    <p className="font-semibold">排班警告 ({warnings.length})：</p>
                    <ul className="list-disc pl-4 space-y-1">
                        {warnings.slice(0, 3).map((w, i) => <li key={i}>{w}</li>)}
                        {warnings.length > 3 && <li>...以及其他 {warnings.length - 3} 個問題。</li>}
                    </ul>
                </div>
            </div>
          </div>
      )}

      <RosterTable 
        key={gridKey}
        year={config.year}
        month={config.month}
        employees={employees}
        baseTarget={baseTarget}
        onCellClick={handleCellClick}
        selectedSymbol={selectedSymbol}
        config={config}
        activeScenario={activeThursdayScenario}
        usedTuesdayReduction={usedTuesdayReduction}
      />
    </div>
  );
};

export default App;

