                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default Controls;

import React from 'react';
import { Calendar, Users, Calculator, Printer, Trash2, Eraser, MousePointer2 } from 'lucide-react';
import { SchedulingConfig, ThursdayScenario, Employee, ShiftSymbol, Tool } from './types';
import { SCENARIO_DESCRIPTIONS, CELL_STYLES } from './constants';
import { getMonthlySpecialHolidays } from './scheduleGenerator';

interface ControlsProps {
  config: SchedulingConfig;
  setConfig: React.Dispatch<React.SetStateAction<SchedulingConfig>>;
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  onGenerate: () => void;
  baseTarget: number;
  stats?: {
      totalDemand: number;
      totalCapacity: number;
      suggestedSpecialLeaves: number;
  };
  selectedSymbol: Tool;
  setSelectedSymbol: (s: Tool) => void;
  onOpenClearModal: () => void;
  activeScenario?: ThursdayScenario;
  usedTuesdayReduction?: boolean;
}

const Controls: React.FC<ControlsProps> = ({ 
    config, setConfig, employees, setEmployees, onGenerate, baseTarget, stats,
    selectedSymbol, setSelectedSymbol, onOpenClearModal, activeScenario, usedTuesdayReduction
}) => {
  const monthlyHolidays = getMonthlySpecialHolidays(config.year, config.month, config.jan1WorkDay);

  const updateStaffName = (index: number, newName: string) => {
    const updated = [...employees];
    updated[index].name = newName;
    setEmployees(updated);
  };

  const updateStaffTarget = (index: number, val: string) => {
    const updated = [...employees];
    updated[index].customTarget = val === '' ? undefined : parseInt(val);
    setEmployees(updated);
  };

  const addStaff = () => {
      const newId = (Math.max(...employees.map(e => parseInt(e.id) || 0)) + 1).toString();
      setEmployees([...employees, { 
          id: newId, 
          name: `員工 ${newId}`, 
          shifts: {}, 
          generatedShiftCount: 0,
          targetDeduction: 0
      }]);
      setConfig(prev => ({ ...prev, staffIds: [...prev.staffIds, newId] }));
  };

  const removeStaff = (index: number) => {
      if (employees.length <= 1) return;
      const toRemove = employees[index];
      const updated = employees.filter((_, i) => i !== index);
      setEmployees(updated);
      setConfig(prev => ({ ...prev, staffIds: prev.staffIds.filter(id => id !== toRemove.id) }));
  };

  const handlePrint = () => {
      window.print();
  };

  const shiftTools: string[] = ['A', 'B', 'C', 'X'];
  const symbols: ShiftSymbol[] = ['O', '特', '婚', '產', '年', '喪'];

  return (
    <div className="bg-white border-b border-gray-200 shadow-sm sticky top-0 z-50 print:hidden transition-all">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-3">

        {/* Top Header Row with Title, Toolbox, and Print */}
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
            {/* Title Section */}
            <div className="flex items-center">
                <h1 className="text-xl xl:text-2xl font-black text-gray-800 flex items-center gap-2 whitespace-nowrap">
                    <Calendar className="w-6 h-6 text-indigo-600" />
                    ShiftFlow
                </h1>
            </div>

            {/* Navigation / Toolbox / Actions Section */}
            <div className="flex flex-col md:flex-row items-center gap-3">

                {/* Main Edit Toolbox - Capsule Style */}
                <div className="flex items-center gap-1 bg-gray-50 border border-gray-200 p-1 rounded-2xl shadow-inner">

                    {/* Mode Group: Pointer & Eraser */}
                    <div className="flex items-center gap-1 pr-1 mr-1 border-r border-gray-200">
                        <button
                            onClick={() => setSelectedSymbol(null)}
                            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all
                                ${selectedSymbol === null 
                                    ? 'bg-indigo-600 text-white shadow-lg scale-105' 
                                    : 'text-gray-400 hover:bg-gray-200 hover:text-gray-600'}
                            `}
                            title="選取模式"
                        >
                            <MousePointer2 className="w-4.5 h-4.5" />
                        </button>
                        <button
                            onClick={() => setSelectedSymbol(selectedSymbol === 'eraser' ? null : 'eraser')}
                            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all
                                ${selectedSymbol === 'eraser' 
                                    ? 'bg-red-500 text-white shadow-lg scale-105' 
                                    : 'text-gray-400 hover:bg-gray-200 hover:text-gray-600'}
                            `}
                            title="橡皮擦"
                        >
                            <Eraser className="w-4.5 h-4.5" />
                        </button>
                    </div>

                    {/* Shifts Group: A, B, C, X */}
                    <div className="flex items-center gap-1 pr-1 mr-1 border-r border-gray-200">
                        {shiftTools.map(s => (
                            <button
                                key={s}
                                onClick={() => setSelectedSymbol(selectedSymbol === s ? null : s)}
                                className={`w-9 h-9 rounded-xl text-xs font-black flex items-center justify-center border transition-all
                                    ${selectedSymbol === s 
                                        ? 'border-indigo-500 bg-indigo-50 text-indigo-700 ring-2 ring-indigo-500/20 scale-105' 
                                        : 'border-transparent bg-transparent text-gray-500 hover:bg-white hover:border-gray-300'}
                                `}
                            >
                                {s}
                            </button>
                        ))}
                    </div>

                    {/* Special Symbols Group */}
                    <div className="flex items-center gap-1">
                        {symbols.map(s => (
                            <button
                                key={s}
                                onClick={() => setSelectedSymbol(selectedSymbol === s ? null : s)}
                                className={`w-9 h-9 rounded-xl text-[10px] font-black flex items-center justify-center border transition-all
                                    ${selectedSymbol === s 
                                        ? 'ring-2 ring-indigo-400 scale-110 z-10 shadow-md' 
                                        : 'hover:border-gray-400 border-transparent'}
                                    ${CELL_STYLES[s] || 'bg-white'}
                                `}
                            >
                                {s}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Secondary Actions */}
                <div className="flex items-center gap-2">
                    <button 
                        onClick={handlePrint}
                        className="flex items-center gap-2 px-4 py-2 text-sm font-bold text-gray-700 bg-white hover:bg-gray-100 rounded-xl transition-all border border-gray-200 shadow-sm"
                    >
                        <Printer className="w-4 h-4" />
                        <span>列印/PDF</span>
                    </button>
                </div>
            </div>
        </div>

        {/* Configuration Section - Always Open Now */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 mt-4 pt-4 border-t border-gray-100">
            <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-4">

                {/* 1. Date & Holiday Config */}
                <div className="p-4 bg-gray-50/50 rounded-2xl border border-gray-100 space-y-3">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                        📅 日期設定
                    </h3>
                    <div className="flex gap-2">
                        <div className="relative flex-1">
                            <input 
                                type="number"
                                value={config.year}
                                onChange={(e) => setConfig({...config, year: parseInt(e.target.value) || 0})}
                                className="block w-full rounded-xl border-gray-200 py-1.5 px-3 text-xs font-bold text-gray-700 focus:ring-indigo-500"
                            />
                            <span className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] text-gray-400">年</span>
                        </div>
                        <select 
                            value={config.month}
                            onChange={(e) => setConfig({...config, month: parseInt(e.target.value)})}
                            className="block flex-1 rounded-xl border-gray-200 py-1.5 px-3 text-xs font-bold text-gray-700 focus:ring-indigo-500"
                        >
                            {Array.from({length: 12}, (_, i) => (
                                <option key={i} value={i}>{i + 1}月</option>
                            ))}
                        </select>
                    </div>
                    <div className="flex items-center gap-2 pt-1">
                        <input 
                            type="checkbox"
                            id="jan1WorkDay"
                            checked={config.jan1WorkDay}
                            onChange={(e) => setConfig({...config, jan1WorkDay: e.target.checked})}
                            className="rounded text-indigo-600 focus:ring-indigo-500 w-3.5 h-3.5"
                        />
                        <label htmlFor="jan1WorkDay" className="text-[10px] text-gray-500 font-bold cursor-pointer select-none">
                            1/1 元旦不休診
                        </label>
                    </div>
                </div>

                {/* 2. Demand Settings */}
                <div className="p-4 bg-gray-50/50 rounded-2xl border border-gray-100">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">
                        👥 人力需求 (平日)
                    </h3>
                    <div className="flex gap-2">
                        {['A', 'B', 'C'].map(shift => (
                            <div key={shift} className="flex-1 bg-white p-2 rounded-xl border border-gray-100 text-center">
                                <span className="text-[9px] text-gray-400 block font-bold mb-1">{shift} 班</span>
                                <input 
                                    type="number" min="0" max="20"
                                    value={(config as any)[`reqStandard${shift}`]}
                                    onChange={(e) => setConfig({...config, [`reqStandard${shift}`]: parseInt(e.target.value) || 0})}
                                    className="w-full border-none p-0 text-center font-black text-indigo-600 text-sm focus:ring-0"
                                />
                            </div>
                        ))}
                    </div>
                </div>

                {/* 3. Stats & Mode Summary */}
                <div className="p-4 bg-indigo-600 rounded-2xl text-white shadow-lg shadow-indigo-100 flex flex-col justify-center">
                    <div className="flex justify-between items-center text-xs">
                        <span className="opacity-80 font-bold uppercase tracking-wider">本月基準目標</span>
                        <span className="text-xl font-black">{baseTarget} 節</span>
                    </div>
                    <div className="mt-2 pt-2 border-t border-indigo-400/50 flex justify-between items-center text-[10px] font-bold">
                        <span className="opacity-80">週四模式</span>
                        <span className="bg-indigo-500 px-2 py-0.5 rounded-full">{activeScenario || 'Auto'}</span>
                    </div>
                </div>

                {/* 4. Main Generator Action */}
                <div className="flex flex-col gap-2">
                    <button 
                        onClick={onGenerate}
                        className="flex-1 bg-indigo-600 text-white px-4 py-3 rounded-2xl shadow-lg shadow-indigo-200 hover:bg-indigo-700 font-black flex items-center justify-center gap-2 transition-all active:scale-95 text-sm uppercase tracking-widest"
                    >
                        <Calculator className="w-5 h-5" />
                        自動排班
                    </button>
                    <button 
                        onClick={onOpenClearModal}
                        className="text-[10px] font-black text-red-400 hover:text-red-600 uppercase flex items-center justify-center gap-1.5 py-1.5 transition-colors"
                    >
                        <Trash2 className="w-3.5 h-3.5" />
                        重設班表
                    </button>
                </div>
            </div>

            {/* Right Column: Mini Staff List */}
            <div className="lg:col-span-4 bg-white p-4 rounded-2xl border border-gray-200 flex flex-col shadow-sm max-h-[160px]">
                <div className="flex justify-between items-center mb-2">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                        <Users className="w-4 h-4" /> 員工名單
                    </h3>
                    <button onClick={addStaff} className="text-[9px] font-black text-indigo-600 hover:underline">+ 新增</button>
                </div>
                <div className="overflow-y-auto space-y-1.5 pr-1 custom-scrollbar">
                    {employees.map((emp, idx) => (
                        <div key={emp.id} className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-lg border border-gray-100">
