                                className="flex-1 text-[11px] bg-transparent border-none focus:ring-0 p-0 font-bold text-gray-700" 
                                value={emp.name} 
                                onChange={(e) => updateStaffName(idx, e.target.value)}
                            />
                            <div className="flex items-center gap-1 bg-white px-1.5 py-0.5 rounded border border-gray-100">
                                <span className="text-[8px] text-gray-400 font-bold">🎯</span>
