                                    className="w-6 text-[10px] text-center border-none bg-transparent p-0 font-black text-indigo-600 focus:ring-0"
                                    value={emp.customTarget ?? ''}
                                    placeholder={baseTarget.toString()}
                                    onChange={(e) => updateStaffTarget(idx, e.target.value)}
                                />
                            </div>
                            <button onClick={() => removeStaff(idx)} className="text-gray-300 hover:text-red-500">
                                <Trash2 className="w-3 h-3" />
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Controls;

