                            <div key={emp.id} className="flex items-center gap-2 bg-gray-50 px-2 py-1.5 rounded-lg border border-gray-100">
                                <input 
                                    className="flex-1 bg-transparent border-none focus:ring-0 p-0 text-[11px] font-bold text-gray-700" 
                                    value={emp.name} 
                                    onChange={(e) => updateStaffName(idx, e.target.value)}
