                                <div className="flex items-center gap-1 bg-white px-1.5 py-0.5 rounded border border-gray-100">
                                    <span className="text-[8px] text-gray-400">🎯</span>
                                    <input 
                                        className="w-5 text-center border-none bg-transparent p-0 text-[10px] font-black text-indigo-600 focus:ring-0"
                                        value={emp.customTarget ?? ''}
                                        placeholder={baseTarget.toString()}
                                        onChange={(e) => updateStaffTarget(idx, e.target.value)}
                                    />
                                </div>
                                <button onClick={() => removeStaff(idx)} className="text-gray-300 hover:text-red-500">
                                    <Trash2 className="w-3 h-3" />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

