              <th className="sticky right-0 z-30 bg-white border border-gray-300 p-1 w-[40px] min-w-[40px] text-center text-xs font-bold text-gray-700 print:border-black print:static print:bg-transparent print:min-w-[40px]">
                統計
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {employees.map((emp, idx) => {
               const effectiveTarget = (emp.customTarget ?? baseTarget) - emp.targetDeduction;
               const diff = emp.generatedShiftCount - effectiveTarget;

               return (
                <React.Fragment key={emp.id}>
                    <tr className="hover:bg-gray-50 transition-colors h-8 print:h-6 print:break-inside-avoid border-t-2 border-gray-300 print:border-black">
                        <td rowSpan={3} className="sticky left-0 z-10 bg-white border-r border-b border-gray-300 px-0 py-1 font-bold text-gray-800 text-center text-lg shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] print:shadow-none print:border-black print:static print:text-xs align-middle [writing-mode:vertical-rl] tracking-widest">
                            {emp.name}
                        </td>

                        <td className="sticky left-[36px] z-10 bg-gray-50/50 border-r border-b border-gray-300 text-center text-[10px] text-gray-500 font-medium align-middle print:border-black print:static print:text-xs">
                            早
                        </td>

                        {daysArray.map(day => {
                            const dateKey = `${year}-${month}-${day}`;
                            const cellData = emp.shifts[dateKey];
                            const { isSunday } = getDayInfo(day);
                            const isSymbol = !Array.isArray(cellData) && cellData;
                            const shifts = Array.isArray(cellData) ? cellData : [];

                            if (isSymbol) {
                                return (
                                    <td 
                                        key={day} 
                                        rowSpan={3}
                                        onClick={() => handleCellClick(idx, day)}
                                        className={`border border-b border-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                            ${selectedSymbol ? 'cursor-cell' : ''}
                                            ${isSunday ? 'cursor-not-allowed opacity-50' : ''}
                                        `}
                                    >
                                        <SymbolBadge symbol={cellData as ShiftSymbol} />
                                    </td>
                                );
                            }

                            return (
                                <td 
                                    key={day} 
                                    onClick={() => handleCellClick(idx, day, 'A')}
                                    className={`border border-gray-200 border-r-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                        ${isSunday ? 'bg-red-50/30 cursor-not-allowed' : ''}
                                        ${selectedSymbol && !isSunday ? 'cursor-cell' : ''}
                                    `}
                                >
                                    <div className="flex items-center justify-center h-full w-full">
                                        {shifts.includes('A') && <ShiftBadge type="A" />}
                                        {shifts.includes('Xa') && <ShiftBadge type="Xa" />}
                                    </div>
                                </td>
                            );
                        })}

                        <td rowSpan={3} className="sticky right-0 z-10 bg-white border-l border-b border-gray-300 px-0.5 text-center shadow-[-2px_0_5px_-2px_rgba(0,0,0,0.1)] print:shadow-none print:border-black print:static align-middle">
                            <div className="flex flex-col items-center justify-center text-xs leading-tight print:text-xs">
                                <span className="font-bold text-indigo-600 text-sm print:text-black print:text-sm">{emp.generatedShiftCount}</span>
                                <span className="text-gray-400 text-[10px] print:text-gray-600">/ {effectiveTarget}</span>
                                {Math.abs(diff) > 2 && (
                                    <span className={`font-bold text-[10px] ${diff > 0 ? 'text-green-500' : 'text-red-500'} print:hidden`}>
                                        {diff > 0 ? `+${diff}` : diff}
                                    </span>
                                )}
                            </div>
                        </td>
                    </tr>

                    <tr className="hover:bg-gray-50 transition-colors h-8 print:h-6 print:break-inside-avoid">
                        <td className="sticky left-[36px] z-10 bg-gray-50/50 border-r border-b border-gray-300 text-center text-[10px] text-gray-500 font-medium align-middle print:border-black print:static print:text-xs">
                            中
                        </td>
                         {daysArray.map(day => {
                            const dateKey = `${year}-${month}-${day}`;
                            const cellData = emp.shifts[dateKey];
                            const { isSunday } = getDayInfo(day);
                            const isSymbol = !Array.isArray(cellData) && cellData;
                            const shifts = Array.isArray(cellData) ? cellData : [];

                            if (isSymbol) return null;

                            return (
                                <td 
                                    key={day} 
                                    onClick={() => handleCellClick(idx, day, 'B')}
                                    className={`border border-gray-200 border-r-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                        ${isSunday ? 'bg-red-50/30 cursor-not-allowed' : ''}
                                        ${selectedSymbol && !isSunday ? 'cursor-cell' : ''}
                                    `}
                                >
                                    <div className="flex items-center justify-center h-full w-full">
                                        {shifts.includes('B') && <ShiftBadge type="B" />}
                                        {shifts.includes('Xb') && <ShiftBadge type="Xb" />}
                                    </div>
                                </td>
                            );
                        })}
                    </tr>

                    <tr className="hover:bg-gray-50 transition-colors h-8 print:h-6 print:break-inside-avoid">
                        <td className="sticky left-[36px] z-10 bg-gray-50/50 border-r border-b border-gray-300 text-center text-[10px] text-gray-500 font-medium align-middle print:border-black print:static print:text-xs">
                            晚
                        </td>
                        {daysArray.map(day => {
                            const dateKey = `${year}-${month}-${day}`;
                            const cellData = emp.shifts[dateKey];
                            const { isSunday } = getDayInfo(day);
                            const isSymbol = !Array.isArray(cellData) && cellData;
                            const shifts = Array.isArray(cellData) ? cellData : [];

                            if (isSymbol) return null;

                            return (
                                <td 
                                    key={day} 
                                    onClick={() => handleCellClick(idx, day, 'C')}
                                    className={`border border-b border-gray-300 p-0 text-center align-middle cursor-pointer hover:bg-indigo-50 relative print:border-black 
                                        ${isSunday ? 'bg-red-50/30 cursor-not-allowed' : ''}
                                        ${selectedSymbol && !isSunday ? 'cursor-cell' : ''}
                                    `}
                                >
                                    <div className="flex items-center justify-center h-full w-full">
                                        {shifts.includes('C') && <ShiftBadge type="C" />}
                                        {shifts.includes('Xc') && <ShiftBadge type="Xc" />}
                                    </div>
                                </td>
                            );
                        })}
                    </tr>
                </React.Fragment>
               );
            })}
          </tbody>

          <tfoot className="bg-gray-50 sticky bottom-0 z-20 shadow-[0_-2px_4px_rgba(0,0,0,0.1)] print:table-footer-group print:shadow-none print:static transition-all duration-300">
            <tr>
              <td colSpan={2} className="sticky left-0 z-30 bg-gray-100 border border-gray-300 p-0 font-bold text-gray-600 text-center text-xs print:border-black print:static print:bg-transparent">
                <button 
                  onClick={() => setIsStatsExpanded(!isStatsExpanded)}
                  className="w-full h-full flex items-center justify-center gap-1 py-2 hover:bg-gray-200 transition-colors focus:outline-none"
                  title={isStatsExpanded ? "摺疊統計" : "展開統計"}
                >
                  <span className="[writing-mode:vertical-rl] text-[10px]">統計</span>
                  {isStatsExpanded ? <ChevronDown className="w-3 h-3" /> : <ChevronUp className="w-3 h-3" />}
                </button>
              </td>
              {daysArray.map(day => {
                  const date = new Date(year, month, day);
                  const dateKey = `${year}-${month}-${day}`;
                  const { isSunday } = getDayInfo(day);
                  const req = getDailyRequirements(date, config, activeScenario, usedTuesdayReduction);

                  let countA = 0, countB = 0, countC = 0;
                  employees.forEach(e => {
                      const cell = e.shifts[dateKey];
                      if (Array.isArray(cell)) {
                          if (cell.includes('A')) countA++;
                          if (cell.includes('B')) countB++;
                          if (cell.includes('C')) countC++;
                      }
                  });

                  if (isSunday) return <td key={day} className="border border-gray-300 bg-red-50/50 print:border-black"></td>;

                  const badA = countA !== req.A;
                  const badB = countB !== req.B;
                  const badC = countC !== req.C;
                  const isReduced = usedTuesdayReduction && date.getDay() === 2;

                  if (!isStatsExpanded) {
                      const hasError = badA || badB || badC;
                      return (
                          <td key={day} className={`border border-gray-300 p-0.5 h-6 print:border-black ${hasError ? 'bg-red-50' : ''}`}>
                              {hasError && <div className="w-2 h-2 rounded-full bg-red-500 mx-auto"></div>}
                          </td>
                      );
                  }

                  return (
                      <td key={day} className="border border-gray-300 p-0.5 align-top print:border-black">
                          <div className="flex flex-col items-center text-[10px] leading-tight py-1 print:text-[8px]">
                              {req.A > 0 && (
                                  <div className={badA ? 'text-red-600 font-bold' : 'text-gray-500 print:text-black'}>
                                      A:{countA}
                                  </div>
                              )}
                              {req.B > 0 && (
                                  <div className={badB ? 'text-red-600 font-bold' : isReduced ? 'text-green-600 font-bold' : 'text-gray-500 print:text-black'}>
                                      B:{countB}
                                  </div>
                              )}
                              {req.C > 0 && (
                                  <div className={badC ? 'text-red-600 font-bold' : isReduced ? 'text-green-600 font-bold' : 'text-gray-500 print:text-black'}>
                                      C:{countC}
                                  </div>
                              )}
                          </div>
                      </td>
                  );
              })}
              <td className="sticky right-0 z-30 bg-gray-100 border border-gray-300 print:border-black print:static"></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

export default RosterTable;

export type ShiftType = 'A' | 'B' | 'C' | 'Xa' | 'Xb' | 'Xc';
export type ShiftSymbol = 'X' | 'O' | '特' | '婚' | '產' | '年' | '喪';

// Union for cell content
export type CellData = ShiftType[] | ShiftSymbol;

// New type for the selected tool in UI
export type Tool = ShiftSymbol | string | 'eraser' | null;

export interface Employee {
  id: string;
  name: string;
  // dateKey -> array of shifts (e.g. ['A', 'B']) OR single symbol string
  shifts: Record<string, CellData>; 

  // Track which dates were manually modified by the user
  // dateKey -> true
  manualEntries?: Record<string, boolean>;

  // Custom target override (optional). If null, use calculated default.
  customTarget?: number;

  // Stats for display
  generatedShiftCount: number; // Actual shifts assigned (A=1, B=1...)
  targetDeduction: number; // Points to deduct from target based on symbols
  deficit?: number; // Internal use for sorting
}

export enum ThursdayScenario {
  A = 'A', // A=5, B=5
  B = 'B', // A=5, B=4
  C = 'C', // A=4, B=4
  C_Plus_Tue = 'C_Plus_Tue', // A=4, B=4 + Tue Reduced
}

export interface SchedulingConfig {
  year: number;
  month: number;
  staffIds: string[];

  // Daily Requirements
  reqStandardA: number;
  reqStandardB: number;
  reqStandardC: number;
  reqSaturdayA: number;

  // Thursday Logic (Auto-selected usually, but kept in config if we want to force it per week)
  thursdayMode: 'Auto' | ThursdayScenario;

  // Year Holiday Date Range (YYYY-MM-DD)
  yearHolidayStart: string;
  yearHolidayEnd: string;

  // Jan 1st Configuration
  jan1WorkDay: boolean;

  // Auto Balance Configuration
  autoBalanceOffToSpecial: boolean;
}

export interface ScheduleResult {
  employees: Employee[];
  warnings: string[];
  stats: {
    totalDemand: number;
    totalCapacity: number;
    suggestedSpecialLeaves: number;
  };
  usedThursdayScenario: ThursdayScenario;
  usedTuesdayReduction: boolean;
}

import React, { useState, useEffect } from 'react';
import Controls from './components/Controls';
import RosterTable from './components/RosterTable';
import ClearModal from './components/ClearModal';
import { SchedulingConfig, Employee, ThursdayScenario, Tool, ShiftType, ShiftSymbol } from './types';
import { generateSchedule, calculateBaseTarget, validateSchedule, recalculateEmployeeStats, calculateOverviewStats } from './services/scheduleGenerator';

const STORAGE_KEY = 'shiftflow_data_v1';

const App: React.FC = () => {
  const today = new Date();

  // -- State --
  // Initialize with 8 employees by default as requested
  const [employees, setEmployees] = useState<Employee[]>(
    Array.from({ length: 8 }).map((_, idx) => ({
      id: (idx + 1).toString(),
      name: `員工 ${idx + 1}`,
      shifts: {},
      manualEntries: {},
      generatedShiftCount: 0,
      targetDeduction: 0
    }))
  );

  const [config, setConfig] = useState<SchedulingConfig>({
    year: today.getFullYear(),
    month: today.getMonth(),
    staffIds: Array.from({ length: 8 }).map((_, idx) => (idx + 1).toString()),

    reqStandardA: 5,
    reqStandardB: 5,
    reqStandardC: 5,
    reqSaturdayA: 5,
    thursdayMode: 'Auto',
    yearHolidayStart: '', 
    yearHolidayEnd: '',
    jan1WorkDay: false,
    autoBalanceOffToSpecial: false
  });

  const [warnings, setWarnings] = useState<string[]>([]);
  const [baseTarget, setBaseTarget] = useState(0);
  const [stats, setStats] = useState<{totalDemand: number, totalCapacity: number, suggestedSpecialLeaves: number} | undefined>(undefined);
  const [activeThursdayScenario, setActiveThursdayScenario] = useState<ThursdayScenario>(ThursdayScenario.A);
  const [usedTuesdayReduction, setUsedTuesdayReduction] = useState(false);

  const [selectedSymbol, setSelectedSymbol] = useState<Tool>(null);

  const [isClearModalOpen, setIsClearModalOpen] = useState(false);
  const [gridKey, setGridKey] = useState(0);

  // -- Persistence --
  useEffect(() => {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
          try {
              const parsed = JSON.parse(saved);
              if (parsed.config) {
                 const loadedConfig = parsed.config;
                 // Migration checks
                 if (loadedConfig.yearHolidayCount !== undefined) delete loadedConfig.yearHolidayCount;
                 if (loadedConfig.jan1WorkDay === undefined) loadedConfig.jan1WorkDay = false;
                 if (loadedConfig.autoBalanceOffToSpecial === undefined) loadedConfig.autoBalanceOffToSpecial = false;
                 setConfig(loadedConfig);
              }
              if (parsed.employees) {
                  const loadedEmployees = parsed.employees.map((e: any) => ({
                      ...e,
                      manualEntries: e.manualEntries || {}
                  }));
                  setEmployees(loadedEmployees);
              }
              if (parsed.stats) setStats(parsed.stats);
              // Ensure type safety for enum from JSON
              if (parsed.activeThursdayScenario) setActiveThursdayScenario(parsed.activeThursdayScenario as ThursdayScenario);
              if (parsed.usedTuesdayReduction) setUsedTuesdayReduction(parsed.usedTuesdayReduction);
          } catch (e) {
              console.error("Failed to load saved data", e);
          }
      }
  }, []);

  useEffect(() => {
      const data = { config, employees, stats, activeThursdayScenario, usedTuesdayReduction };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [config, employees, stats, activeThursdayScenario, usedTuesdayReduction]);


  // -- Effects --
  useEffect(() => {
     setBaseTarget(calculateBaseTarget(config.year, config.month, config.yearHolidayStart, config.yearHolidayEnd, config.jan1WorkDay));

     const updatedEmployees = employees.map(emp => recalculateEmployeeStats(emp, config.year, config.month));
     setEmployees(updatedEmployees);

     const newStats = calculateOverviewStats(config, updatedEmployees, activeThursdayScenario, usedTuesdayReduction);
     setStats(newStats);

  }, [config.year, config.month, config.yearHolidayStart, config.yearHolidayEnd, config.jan1WorkDay, config.reqStandardA, config.reqStandardB, config.reqStandardC, config.reqSaturdayA]);

  useEffect(() => {
    const newWarnings = validateSchedule(employees, config, activeThursdayScenario, usedTuesdayReduction);
    setWarnings(newWarnings);
  }, [employees, config, activeThursdayScenario, usedTuesdayReduction]);

  // -- Handlers --

  const handleGenerate = () => {
    const result = generateSchedule(config, employees);

    setEmployees(result.employees);
    setWarnings(result.warnings);
    setStats(result.stats);
    setActiveThursdayScenario(result.usedThursdayScenario);
    setUsedTuesdayReduction(result.usedTuesdayReduction);
    setGridKey(prev => prev + 1);
  };

  const handleClear = (mode: 'generated' | 'all') => {
      const prefix = `${config.year}-${config.month}-`;

      const newEmployees = employees.map(emp => {
          const newShifts = { ...emp.shifts };
          const newManualEntries = { ...(emp.manualEntries || {}) };

          Object.keys(newShifts).forEach(key => {
              if (!key.startsWith(prefix)) return;

              const cellValue = newShifts[key];
              const isManual = newManualEntries[key];

              if (mode === 'all') {
                  delete newShifts[key];
                  delete newManualEntries[key];
              } else if (mode === 'generated') {
                  if (Array.isArray(cellValue) && !isManual) {
                      delete newShifts[key];
                  }
              }
          });

          return recalculateEmployeeStats({
              ...emp,
              shifts: newShifts,
              manualEntries: newManualEntries
          }, config.year, config.month);
      });

      setEmployees(newEmployees);
      setIsClearModalOpen(false);
      setGridKey(prev => prev + 1);

      if (mode === 'all') {
          const emptyStats = calculateOverviewStats(config, newEmployees, ThursdayScenario.A, false);
          setStats(emptyStats);
          setActiveThursdayScenario(ThursdayScenario.A);
          setUsedTuesdayReduction(false);
      }
  };

  const handleCellClick = (empIndex: number, day: number, shiftClicked?: ShiftType) => {
      const dateKey = `${config.year}-${config.month}-${day}`;
      const newEmployees = [...employees];
      const emp = newEmployees[empIndex];
      const newShifts = { ...emp.shifts };
      const newManualEntries = { ...(emp.manualEntries || {}) };

      const currentVal = newShifts[dateKey];

      if (selectedSymbol === 'eraser') {
          if (Array.isArray(currentVal) && shiftClicked) {
              const newVal = currentVal.filter(s => {
                  if (shiftClicked === 'A') return s !== 'A' && s !== 'Xa';
                  if (shiftClicked === 'B') return s !== 'B' && s !== 'Xb';
                  if (shiftClicked === 'C') return s !== 'C' && s !== 'Xc';
                  return s !== shiftClicked;
              });

              if (newVal.length === 0) {
                  delete newShifts[dateKey];
                  delete newManualEntries[dateKey];
              } else {
                  newShifts[dateKey] = newVal;
                  newManualEntries[dateKey] = true;
              }
          } else {
              delete newShifts[dateKey];
              delete newManualEntries[dateKey];
          }
      } 
      else if (selectedSymbol && !['A', 'B', 'C', 'X'].includes(selectedSymbol)) {
          newShifts[dateKey] = selectedSymbol as ShiftSymbol;
          newManualEntries[dateKey] = true;
      }
      else {
          let targetShift: string | undefined = selectedSymbol ? selectedSymbol : shiftClicked;

          if (targetShift === 'X') {
              if (shiftClicked === 'A') targetShift = 'Xa';
              else if (shiftClicked === 'B') targetShift = 'Xb';
              else if (shiftClicked === 'C') targetShift = 'Xc';
          }

          const validShifts: string[] = ['A', 'B', 'C', 'Xa', 'Xb', 'Xc'];

          if (targetShift && validShifts.includes(targetShift)) {
              const finalShift = targetShift as ShiftType;
              let currentArr: ShiftType[] = [];
              if (Array.isArray(currentVal)) {
                  currentArr = [...currentVal];
              }

              if (currentArr.includes(finalShift)) {
                  currentArr = currentArr.filter(s => s !== finalShift);
              } else {
                  currentArr.push(finalShift);
                  if (finalShift === 'Xa') currentArr = currentArr.filter(s => s !== 'A');
                  if (finalShift === 'A') currentArr = currentArr.filter(s => s !== 'Xa');
                  if (finalShift === 'Xb') currentArr = currentArr.filter(s => s !== 'B');
                  if (finalShift === 'B') currentArr = currentArr.filter(s => s !== 'Xb');
                  if (finalShift === 'Xc') currentArr = currentArr.filter(s => s !== 'C');
                  if (finalShift === 'C') currentArr = currentArr.filter(s => s !== 'Xc');

                  const sortOrder: Record<string, number> = { 'A':1, 'Xa':1, 'B':2, 'Xb':2, 'C':3, 'Xc':3 };
                  currentArr.sort((a, b) => (sortOrder[a] || 99) - (sortOrder[b] || 99));
              }

              if (currentArr.length === 0) {
                  delete newShifts[dateKey];
                  delete newManualEntries[dateKey];
              } else {
                  newShifts[dateKey] = currentArr;
                  newManualEntries[dateKey] = true;
              }
          }
      }

      emp.shifts = newShifts;
      emp.manualEntries = newManualEntries;

      newEmployees[empIndex] = recalculateEmployeeStats(emp, config.year, config.month);
      setEmployees(newEmployees);

      const newStats = calculateOverviewStats(config, newEmployees, activeThursdayScenario, usedTuesdayReduction);
      setStats(newStats);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-100 font-sans print:bg-white print:h-auto print:block print:overflow-visible">
      <Controls 
        config={config} 
        setConfig={setConfig} 
        employees={employees}
        setEmployees={setEmployees}
        onGenerate={handleGenerate}
        baseTarget={baseTarget}
        stats={stats}
        selectedSymbol={selectedSymbol}
        setSelectedSymbol={setSelectedSymbol}
        onOpenClearModal={() => setIsClearModalOpen(true)}
        activeScenario={activeThursdayScenario}
        usedTuesdayReduction={usedTuesdayReduction}
      />

      <ClearModal 
        isOpen={isClearModalOpen}
        onClose={() => setIsClearModalOpen(false)}
        onConfirm={handleClear}
        monthLabel={`${config.year}年${config.month + 1}月`}
      />

      <RosterTable 
        key={gridKey}
        year={config.year}
        month={config.month}
        employees={employees}
        baseTarget={baseTarget}
        onCellClick={handleCellClick}
        selectedSymbol={selectedSymbol}
        config={config}
        activeScenario={activeThursdayScenario}
        usedTuesdayReduction={usedTuesdayReduction}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Calendar, Users, Calculator, ChevronDown, ChevronUp, Printer, Trash2, Eraser, MousePointer2, Scale } from 'lucide-react';
import { SchedulingConfig, ThursdayScenario, Employee, ShiftSymbol, Tool } from '../types';
import { SCENARIO_DESCRIPTIONS, CELL_STYLES, TARGET_MULTIPLIER } from '../constants';
import { getMonthlySpecialHolidays } from '../services/scheduleGenerator';

interface ControlsProps {
  config: SchedulingConfig;
  setConfig: React.Dispatch<React.SetStateAction<SchedulingConfig>>;
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  onGenerate: () => void;
  baseTarget: number;
  stats?: {
      totalDemand: number;
      totalCapacity: number;
      suggestedSpecialLeaves: number;
  };
  selectedSymbol: Tool;
  setSelectedSymbol: (s: Tool) => void;
  onOpenClearModal: () => void;
  activeScenario?: ThursdayScenario;
  usedTuesdayReduction?: boolean;
}

const Controls: React.FC<ControlsProps> = ({ 
    config, setConfig, employees, setEmployees, onGenerate, baseTarget, stats,
    selectedSymbol, setSelectedSymbol, onOpenClearModal, activeScenario, usedTuesdayReduction
}) => {
  const [isOpen, setIsOpen] = useState(true);
  const monthlyHolidays = getMonthlySpecialHolidays(config.year, config.month, config.jan1WorkDay);

  const updateStaffName = (index: number, newName: string) => {
    const updated = [...employees];
    updated[index].name = newName;
    setEmployees(updated);
  };

  const updateStaffTarget = (index: number, val: string) => {
    const updated = [...employees];
    updated[index].customTarget = val === '' ? undefined : parseInt(val);
    setEmployees(updated);
  };

  const addStaff = () => {
      const newId = (Math.max(...employees.map(e => parseInt(e.id) || 0)) + 1).toString();
      setEmployees([...employees, { 
          id: newId, 
          name: `員工 ${newId}`, 
          shifts: {}, 
          generatedShiftCount: 0,
          targetDeduction: 0
      }]);
      setConfig(prev => ({ ...prev, staffIds: [...prev.staffIds, newId] }));
  };

  const removeStaff = (index: number) => {
      if (employees.length <= 1) return;
      const toRemove = employees[index];
      const updated = employees.filter((_, i) => i !== index);
      setEmployees(updated);
      setConfig(prev => ({ ...prev, staffIds: prev.staffIds.filter(id => id !== toRemove.id) }));
  };

  const handlePrint = () => {
